```java
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;

public class Car {
    private String color;

    public Car(String color) {
        this.color = color;
    }

    public String getColor() {
        return color;
    }
}

public class Main {
    public static Map<String, Long> countColors(List<Car> cars) {
        return cars.stream()
                .collect(Collectors.groupingBy(Car::getColor, Collectors.counting()));
    }

    public static Map.Entry<String, Long> mostPopularColor(Map<String, Long> colorCounts) {
        return colorCounts.entrySet().stream()
                .max(Map.Entry.comparingByValue())
                .orElse(null);
    }

    public static void main(String[] args) {
        List<Car> cars = List.of(new Car("Red"), new Car("Blue"), new Car("Red"), new Car("Green"), new Car("Blue"));

        Map<String, Long> colorCounts = countColors(cars);
        Map.Entry<String, Long> mostPopular = mostPopularColor(colorCounts);

        System.out.println("Most popular color: " + mostPopular.getKey() + ", count: " + mostPopular.getValue());
    }
}
```

In this example, the `countColors` method calculates the count of each color in the list of cars, while the `mostPopularColor` method finds the most popular color by returning the entry with the highest count. The `main` method demonstrates how to use these methods with a sample list of cars. You can modify the code to fit your specific needs, such as defining the Car class or changing the list of cars.

